            children: "\"\"\"\nAnalysis of Lunar Eclipse Visibility\n====================================\n\nThis script reads a catalog of 21st century lunar eclipses from\n‘eclipses.xlsx‘, extracts the times of totality, and determines\nwhich eclipses are visible from:\n    - Cape Fligely\n    - Point Xi on the equator\n\nVisibility is defined as the Moon’s upper limb being above the\ngeometric horizon, corrected for refraction and the Moon’s\nradius.\n\"\"\"\n\nimport pandas as pd\nimport numpy as np\nimport astropy.units as u\nfrom astropy.time import Time, TimeDelta\nfrom astropy.coordinates import EarthLocation, AltAz, get_body\n\n\n# ----------------------------------------------------------------------\n# Load and preprocess the eclipse catalog\n# ----------------------------------------------------------------------\ndef load_eclipses(path: str = \"eclipses.xlsx\") -> pd.DataFrame:\n    \"\"\"\n    Load the lunar eclipse catalog from Excel and standardize columns.\n\n    Parameters\n    ----------\n    path : str\n        Path to the Excel file.\n\n    Returns\n    -------\n    df : pandas.DataFrame\n        DataFrame with standardized columns and auxiliary fields.\n    \"\"\"\n    df = pd.read_excel(path, skiprows=1)\n\n    df = df.rename(columns={\n        \"Unnamed: 0\": \"num\",\n        \"U1\": \"U1\", \"U2\": \"U2\", \"U3\": \"U3\", \"U4\": \"U4\",\n        \"Unnamed: 10\": \"maxt\"\n    })\n\n    months = {m: i for i, m in enumerate(\n        [\"January\",\"February\",\"March\",\"April\",\"May\",\"June\",\n         \"July\",\"August\",\"September\",\"October\",\"November\",\"December\"], 1)}\n    df[\"Month_num\"] = df[\"Month\"].map(months)\n\n    df[\"date\"] = pd.to_datetime(\n        dict(year=df[\"Year\"], month=df[\"Month_num\"], day=df[\"Day\"]),\n        errors=\"coerce\"\n    )\n\n    def frac_to_time(frac):\n        if pd.isna(frac):\n            return np.nan\n        seconds = float(frac) * 24 * 3600\n        h = int(seconds // 3600)\n        m = int((seconds % 3600) // 60)\n        s = int(seconds % 60)\n        return f\"{h:02d}:{m:02d}:{s:02d}\"\n\n    df[\"maxt_str\"] = df[\"maxt\"].apply(frac_to_time)\n\n    return df\n\n\n# ----------------------------------------------------------------------\n# Convert tabulated times into astropy.Time arrays\n# ----------------------------------------------------------------------\ndef build_times(df: pd.DataFrame):\n    \"\"\"\n    Construct astropy.Time objects for total eclipses only.\n\n    Returns\n    -------\n    df_tot : pandas.DataFrame\n        Subset containing only total eclipses (U2 and U3 defined).\n    t2, t3, tmax : astropy.Time\n        Times of second contact, third contact, and maximum eclipse.\n    \"\"\"\n    df_tot = df[df[\"U2\"].notna() & df[\"U3\"].notna()].copy()\n\n    def to_iso(dates, times):\n        iso_list = []\n        for d, t in zip(dates, times):\n            if pd.isna(t) or pd.isna(d):\n                iso_list.append(\"NaT\")\n            else:\n                iso_list.append(f\"{d.strftime(’%Y-%m-%d’)}T{t}\")\n        return np.array(iso_list, dtype=str)\n\n    iso_u2  = to_iso(df_tot[\"date\"], df_tot[\"U2\"])\n    iso_u3  = to_iso(df_tot[\"date\"], df_tot[\"U3\"])\n    iso_max = to_iso(df_tot[\"date\"], df_tot[\"maxt_str\"])\n\n    t2   = Time(iso_u2,  format=\"isot\", scale=\"utc\", out_subfmt=\"date_hms\")\n    t3   = Time(iso_u3,  format=\"isot\", scale=\"utc\", out_subfmt=\"date_hms\")\n    tmax = Time(iso_max, format=\"isot\", scale=\"utc\", out_subfmt=\"date_hms\")\n\n    # adjust for midnight crossings\n    one_day = TimeDelta(1*u.day)\n    t3[tmax > t3] = t3[tmax > t3] + one_day\n    t2[tmax < t2] = t2[tmax < t2] - one_day\n\n    return df_tot, t2, t3, tmax\n\n\n# ----------------------------------------------------------------------\n# Visibility criterion\n# ----------------------------------------------------------------------\ndef visible_mask_for_site(t2, t3, lat_deg, lon_deg=59 + 14/60, height_m=0,\n                          n_samples=11, h_thresh_deg=-(35+16)/60.0):\n    \"\"\"\n    Check eclipse visibility over the full totality interval [U2, U3]\n    Samples each eclipse at ‘n_samples‘ evenly spaced times\n    and returns True if the Moons center altitude exceeds ‘h_thresh_deg‘\n\n    Parameters\n    ----------\n    t2, t3 : astropy.Time\n        Start and end of totality.\n    lat_deg, lon_deg : float\n        Geographic coordinates of the site (degrees).\n    height_m : float\n        Elevation above sea level.\n    n_samples : int, optional\n        Number of samples per eclipse (inclusive of endpoints), default 11.\n    h_thresh_deg : float, optional\n        Altitude threshold (degrees) for the Moons center.\n\n    Returns\n    -------\n    mask : ndarray of bool\n        True if any sample during totality is above the threshold\n        (i.e., visible).\n    \"\"\"\n    loc = EarthLocation(\n        lat=lat_deg*u.deg,\n        lon=lon_deg*u.deg,\n        height=height_m*u.m\n    )\n\n    frac = np.linspace(0.0, 1.0, n_samples)\n    dt = t3 - t2\n    t_grid = t2[:, None] + frac[None, :] * dt[:, None]\n\n    alt = get_body(\"moon\", t_grid.reshape(-1), location=loc)\\\n        .transform_to(AltAz(obstime=t_grid.reshape(-1), location=loc))\\\n        .alt.deg.reshape(len(t2), n_samples)\n\n    return (alt > h_thresh_deg).any(axis=1)\n\n\n# ----------------------------------------------------------------------\n# Main pipeline\n# ----------------------------------------------------------------------\ndef analyze_visibility(path=\"eclipses.xlsx\"):\n    \"\"\"\n    Analyze visibility of total lunar eclipses from Cape Fligely\n    and point Xi.\n    \"\"\"\n    df = load_eclipses(path)\n    df_tot, t2, t3, tmax = build_times(df)\n\n    events = df_tot[\"num\"].to_numpy()\n\n    # two sites\n    vis_XI = visible_mask_for_site(t2, t3, lat_deg=0.0)\n    vis_FL = visible_mask_for_site(t2, t3, lat_deg=81 + 51/60.0)\n\n    xi_list  = events[vis_XI].tolist()\n    fl_list  = events[vis_FL].tolist()\n    both     = sorted(set(xi_list) & set(fl_list))\n\n    print(\"Total eclipses:\", len(events))\n    print(\"Visible from point Xi:\", len(xi_list))\n    print(\"Visible from Cape Fligely:\", len(fl_list))\n    print(\"Visible from both:\", len(both))\n\n    return xi_list, fl_list, both\n\n\n# ----------------------------------------------------------------------\n# Entry point\n# ----------------------------------------------------------------------\nif __name__ == \"__main__\":\n    xi_list, fl_list, both = analyze_visibility(\"eclipses.xlsx\")\n"
